421	pub fn paint_order(ctx: &Ctx, children: &[usize]) -> Vec<usize> {
422	    let mut flow: Vec<usize> = Vec::new();
423	    let mut pinned: Vec<usize> = Vec::new();
424	    for &c in children {
425	        if ctx.comp[c].pin.is_some() {
426	            pinned.push(c);
427	        } else {
428	            flow.push(c);
429	        }
430	    }
431	    flow.extend(pinned);
432	    flow
433	}
