580	pub fn prop_str(ctx: &Ctx, i: usize, k: &str) -> Option<String> {
581	    let v = ctx.nodes[i].props.get(k)?;
582	    match single_term(v)? {
583	        Term::Str(x, _) => Some(x.clone()),
584	        Term::Ident(x, _) => Some(x.clone()),
585	        _ => None,
586	    }
587	}
