589	pub fn prop_nums(ctx: &Ctx, i: usize, k: &str) -> Vec<f64> {
590	    match ctx.nodes[i].props.get(k) {
591	        Some(v) => value_nums(&ctx.sheet.env, v),
592	        None => vec![],
593	    }
