749	fn shadow_filter(ctx: &Ctx, i: usize, out: &mut Out) -> Option<String> {
750	    let xs = prop_nums(ctx, i, "shadow");
751	    if xs.len() < 3 {
752	        return None;
753	    }
754	    let theme = crate::theme::resolve("default").unwrap();
755	    let col = theme.light_value("shadow-color").unwrap_or_default();
756	    let key = format!("{},{},{},{}", f4(xs[0]), f4(xs[1]), f4(xs[2]), col);
757	    let id = format!("lini-shadow-{}", hash8(&key));
758	    let def = format!(
759	        "<filter id=\"{}\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\"><feDropShadow dx=\"{}\" dy=\"{}\" stdDeviation=\"{}\" flood-color=\"{}\"/></filter>",
760	        id,
761	        f4(xs[0]),
762	        f4(xs[1]),
763	        f4(xs[2]),
764	        col
765	    );
766	    if !out.defs.contains(&def) {
767	        out.defs.push(def);
768	    }
769	    Some(id)
770	}
771	
772	pub fn render_node(ctx: &Ctx, i: usize, ind_n: usize, s: &mut String, out: &mut Out) -> Result<(), Diag> {
773	    let n = &ctx.nodes[i];
774	    let c = &ctx.comp[i];
775	    if n.prim == Prim::Text {
776	        return render_text(ctx, i, ind_n, s, out);
777	    }
778	    let href = prop_str(ctx, i, "href");
779	    let mut ind_n = ind_n;
780	    if let Some(h) = &href {
781	        s.push_str(&format!("{}<a href=\"{}\">\n", ind(ind_n), xml_escape(h)));
782	        ind_n += 2;
783	    }
784	    let cls = node_classes(ctx, i, out);
785	    let style = inline_style(ctx, i, out, false)?;
786	    let mut head = format!("{}<g class=\"{}\"", ind(ind_n), cls);
787	    if let Some(id) = &n.id {
788	        head.push_str(&format!(" data-id=\"{}\"", xml_escape(id)));
789	    }
790	    if !style.is_empty() {
791	        head.push_str(&format!(" style=\"{}\"", xml_escape(&style)));
792	    }
793	    let tx = n.x + c.translate.0 + n.geo_off.0;
794	    let ty = n.y + c.translate.1 + n.geo_off.1;
795	    head.push_str(&format!(" transform=\"translate({},{})", f4(tx), f4(ty)));
796	    if c.rotate != 0.0 {
797	        head.push_str(&format!(" rotate({})", f4(c.rotate)));
798	    }
799	    head.push_str("\">\n");
800	    s.push_str(&head);
801	    let ci = ind_n + 2;
802	    if let Some(hint) = prop_str(ctx, i, "hint") {
803	        s.push_str(&format!("{}<title>{}</title>\n", ind(ci), xml_escape(&hint)));
804	    }
805	    if crate::chart::is_chart(ctx, i) {
806	        crate::chart::render(ctx, i, ci, s, out)?;
807	        s.push_str(&format!("{}</g>\n", ind(ind_n)));
808	        if href.is_some() {
809	            s.push_str(&format!("{}</a>\n", ind(ind_n - 2)));
810	        }
811	        return Ok(());
812	    }
813	    let shape = shape_lines(ctx, i);
814	    if shape.iter().any(|l| l.contains("lini-marker")) {
815	        out.markers = true;
816	    }
817	    let multiple = prop_nums(ctx, i, "multiple").first().copied();
818	    let shadow = shadow_filter(ctx, i, out);
819	    let mut si = ci;
820	    if let Some(id) = &shadow {
821	        s.push_str(&format!("{}<g filter=\"url(#{})\">\n", ind(si), id));
822	        si += 2;
823	    }
824	    if let Some(m) = multiple {
825	        s.push_str(&format!("{}<g transform=\"translate({},{})\">\n", ind(si), f4(m), f4(-m)));
826	        for l in &shape {
827	            s.push_str(&format!("{}{}\n", ind(si + 2), l));
828	        }
829	        s.push_str(&format!("{}</g>\n", ind(si)));
830	    }
831	    for l in &shape {
832	        s.push_str(&format!("{}{}\n", ind(si), l));
833	    }
834	    if shadow.is_some() {
835	        s.push_str(&format!("{}</g>\n", ind(ci)));
836	    }
837	    if !n.gutters.is_empty() {
838	        let fill = match ctx.nodes[i].props.get("gap-fill").and_then(single_term) {
839	            Some(t) => color_css(t, &mut out.vars, t.span())?,
840	            None => String::new(),
841	        };
842	        out.gutters = true;
843	        for &(x, y, w, h) in &n.gutters {
844	            s.push_str(&format!(
845	                "{}<rect class=\"lini-gutter\" x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" fill=\"{}\"/>\n",
846	                ind(ci),
847	                f4(x),
848	                f4(y),
849	                f4(w),
850	                f4(h),
851	                xml_escape(&fill)
852	            ));
853	        }
854	    }
855	    let ordered = paint_order(ctx, &n.children);
856	    for ch in ordered {
857	        render_node(ctx, ch, ci, s, out)?;
858	    }
859	    s.push_str(&format!("{}</g>\n", ind(ind_n)));
860	    if href.is_some() {
861	        s.push_str(&format!("{}</a>\n", ind(ind_n - 2)));
862	    }
863	    Ok(())
864	}
