// Syntax tree for a Lini document.

use crate::diag::Span;

#[derive(Debug, Clone)]
pub struct Doc {
    pub sheet: Option<Sheet>,
    pub stmts: Vec<Stmt>,
}

#[derive(Debug, Clone)]
pub struct Sheet {
    pub items: Vec<SheetItem>,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub enum SheetItem {
    Decl(Decl),
    Var(Decl),
    Binding(Binding),
    Rule(Rule),
    Define(Define),
}

#[derive(Debug, Clone)]
pub struct Decl {
    pub name: String,
    pub name_span: Span,
    pub value: Value,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub struct Binding {
    pub name: String,
    pub params: Option<Vec<String>>,
    pub expr: Term,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub struct Rule {
    pub selector: Vec<Compound>,
    pub decls: Vec<Decl>,
    pub span: Span,
}

#[derive(Debug, Clone, Default)]
pub struct Compound {
    pub bars: bool,
    pub type_name: Option<String>, // '-' for the link selector |-|
    pub id: Option<String>,
    pub classes: Vec<String>,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub struct Define {
    pub name: String,
    pub base: String,
    pub decls: Vec<Decl>,
    pub body: Option<Vec<Stmt>>,
    pub span: Span,
    pub head_span: Span,
}

#[derive(Debug, Clone)]
pub struct Value {
    // comma-separated groups, each a space-separated run of terms
    pub groups: Vec<Vec<Term>>,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub enum Term {
    Num(f64, String, Span),
    Percent(f64, String, Span),
    Ident(String, Span),
    Str(String, Span),
    Hash(String, Span),
    Var(String, Span),
    Call(String, Vec<Expr>, Span),
    Group(Expr, Span),
    Tagged(Box<Term>, String, Span), // term ':' tag (draw segment names)
}

impl Term {
    pub fn span(&self) -> Span {
        match self {
            Term::Num(_, _, s)
            | Term::Percent(_, _, s)
            | Term::Ident(_, s)
            | Term::Str(_, s)
            | Term::Hash(_, s)
            | Term::Var(_, s)
            | Term::Call(_, _, s)
            | Term::Group(_, s)
            | Term::Tagged(_, _, s) => *s,
        }
    }
}

#[derive(Debug, Clone)]
pub enum Expr {
    Num(f64, Span),
    Percent(f64, Span),
    Ident(String, Span),
    Str(String, Span),
    Var(String, Span),
    Hash(String, Span),
    Call(String, Vec<Expr>, Span),
    Unary(String, Box<Expr>, Span),
    Bin(String, Box<Expr>, Box<Expr>, Span),
    Ternary(Box<Expr>, Box<Expr>, Box<Expr>, Span),
    Tuple(Vec<Expr>, Span),
    Block(Vec<(String, Expr)>, Box<Expr>, Span), // (a = 1; b = 2; expr)
}

impl Expr {
    pub fn span(&self) -> Span {
        match self {
            Expr::Num(_, s)
            | Expr::Percent(_, s)
            | Expr::Ident(_, s)
            | Expr::Str(_, s)
            | Expr::Var(_, s)
            | Expr::Hash(_, s)
            | Expr::Call(_, _, s)
            | Expr::Unary(_, _, s)
            | Expr::Bin(_, _, _, s)
            | Expr::Ternary(_, _, _, s)
            | Expr::Tuple(_, s)
            | Expr::Block(_, _, s) => *s,
        }
    }
}

#[derive(Debug, Clone)]
pub enum Stmt {
    Node(NodeStmt),
    Text(TextStmt),
    Link(LinkStmt),
}

#[derive(Debug, Clone)]
pub struct NodeStmt {
    pub type_name: Option<String>,
    pub id: Option<String>,
    pub label: Option<(String, Span)>,
    pub classes: Vec<String>,
    pub classes_span: Option<Span>,
    pub style: Option<Vec<Decl>>,
    pub style_span: Option<Span>,
    pub children: Option<Vec<Stmt>>,
    pub span: Span,
    pub head_span: Span,
}

#[derive(Debug, Clone)]
pub struct TextStmt {
    pub text: String,
    pub classes: Vec<String>,
    pub style: Option<Vec<Decl>>,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub enum Endpoint {
    Path(PathRef),
    Node(Box<NodeStmt>),
    Text(String, Span),
}

#[derive(Debug, Clone)]
pub struct PathRef {
    pub parts: Vec<String>,
    pub index: Option<u32>,
    pub anchor: Option<String>,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub struct LinkStmt {
    // groups[i] are fanned endpoints; ops[i] joins groups[i] and groups[i+1]
    pub groups: Vec<Vec<Endpoint>>,
    pub ops: Vec<(String, Span)>,
    pub label: Option<(String, Span)>,
    pub classes: Vec<String>,
    pub style: Option<Vec<Decl>>,
    pub labels: Option<Vec<Stmt>>,
    pub span: Span,
}
// Charts: |chart| (bars, lines, areas, dots, bubbles, bands, marks, axes;
// cartesian or radial) and |pie| (slices). A chart lays out and paints its
// own series children; they are not rendered as ordinary nodes.

use crate::compile::Ctx;
use crate::diag::Diag;
use crate::render::Out;

// Is node `i` a chart or pie container this module paints?
pub fn is_chart(ctx: &Ctx, i: usize) -> bool {
    let l = ctx.comp[i].layout.as_str();
    l == "chart" || l == "pie"
}

// Size the chart (sets ctx.nodes[i].w / h). Children are not laid out by the core.
pub fn measure(ctx: &mut Ctx, i: usize) {
    let n = &mut ctx.nodes[i];
    n.w = 0.0;
    n.h = 0.0;
}

// Paint the chart's inner elements (inside the node's <g>, at indent `ind`).
pub fn render(ctx: &Ctx, i: usize, ind: usize, s: &mut String, out: &mut Out) -> Result<(), Diag> {
    let _ = (ctx, i, ind, s, out);
    Ok(())
}
// `lini desugar`: the document lowered to primitives and `.lini-*` classes.

use crate::diag::Diag;

pub fn desugar(src: &str) -> Result<String, Diag> {
    let _ = crate::parser::parse(src)?;
    Ok(String::new())
}
// Style values: cascade, inheritance, and CSS serialisation.

use crate::ast::{Decl, Expr, Term, Value};
use crate::diag::{Diag, Span};
use crate::eval::{Env, EV};
use crate::util::f4;
use std::collections::HashMap;

// CSS properties in the order they are serialised.
pub const CSS_ORDER: &[&str] = &[
    "fill",
    "stroke",
    "stroke-width",
    "opacity",
    "color",
    "font-family",
    "font-size",
    "font-weight",
    "font-style",
    "text-decoration",
    "text-shadow",
    "stroke-style",
];

pub const INHERITED: &[&str] = &[
    "font-size",
    "font-weight",
    "font-family",
    "font-style",
    "color",
    "letter-spacing",
    "line-spacing",
    "text-transform",
    "text-decoration",
    "text-shadow",
];

pub fn parse_decls(src: &'static str) -> Vec<Decl> {
    let full = format!("{{{}}}", src);
    let lexed = crate::lexer::lex(&full).expect("defaults lex");
    let mut p = crate::parser::Parser::new(&lexed.tokens, &full);
    let (decls, _) = p.parse_style_block().expect("defaults parse");
    decls
}

static DEFAULTS_CACHE: std::sync::OnceLock<HashMap<&'static str, Vec<Decl>>> = std::sync::OnceLock::new();

pub fn type_defaults(name: &str) -> &'static [Decl] {
    let m = DEFAULTS_CACHE.get_or_init(|| {
        let mut m = HashMap::new();
        for t in crate::types::TYPES {
            m.insert(t.name, parse_decls(t.defaults));
        }
        m
    });
    match m.get(name) {
        Some(v) => v,
        None => &[],
    }
}

// --------------------------------------------------------------- values

pub fn single_term(v: &Value) -> Option<&Term> {
    if v.groups.len() == 1 && v.groups[0].len() == 1 {
        Some(&v.groups[0][0])
    } else {
        None
    }
}

pub fn ident_of(v: &Value) -> Option<&str> {
    match single_term(v) {
        Some(Term::Ident(s, _)) => Some(s.as_str()),
        _ => None,
    }
}

pub fn term_num(env: &Env, t: &Term) -> Option<f64> {
    match t {
        Term::Num(v, _, _) => Some(*v),
        Term::Group(e, _) => env.eval(e, &HashMap::new()).ok().and_then(|x| x.num()),
        Term::Call(..) => env.eval_term(t, &HashMap::new()).ok().and_then(|x| x.num()),
        Term::Ident(n, _) => match env.vars.get(n) {
            Some(EV::Num(v)) => Some(*v),
            _ => None,
        },
        _ => None,
    }
}

pub fn value_nums(env: &Env, v: &Value) -> Vec<f64> {
    let mut out = Vec::new();
    for g in &v.groups {
        for t in g {
            if let Some(x) = term_num(env, t) {
                out.push(x);
            }
        }
    }
    out
}

pub fn value_num(env: &Env, v: &Value) -> Option<f64> {
    single_term(v).and_then(|t| term_num(env, t))
}

