// The page is an ordinary container inside its frame [SPEC 15.8], so the blocks
// take a grid: fixed tracks, each sized to the widest and tallest block the
// lattice draws in it, stretched to tile the sheet edge to edge. The
// bottom-right cell is left empty for the title block, which takes no cell at
// all — a `|title-block|` is pulled out of the flow and pinned flush inside the
// frame's corner [SPEC 15.8]. `padding:` clears the frame, which is inset
// 10 mm from the trimmed edge, so no block draws over it.
|page| {
  sheet: a3 landscape; layout: grid; columns: 680, 790, 610; rows: 460, 440, 500; padding: 0; gap: 24; align: stretch; justify: stretch;
} [

  |region#entry| "24 V entry" { cell: 1 1; } [
    // The high-side switch faces its feed: the pfet glyph presents the
    // channel pins on its right, and a half turn re-sides them at the fuse
    // — read at lowering, every text upright [SPEC 16.1] — so the 24 V path
    // runs straight through instead of orbiting the body.
    |Q#Q1| "AOD4185" { symbol: pfet; cell: 2 1; rotate: 180; }
    // `pins: N` gives a connector one column of pins, facing left; the header
    // sits at the sheet's edge, so it is flipped to face its circuit —
    // `mirror: y-axis` re-sides the column with pin 1 still on top, where
    // `rotate: 180` would put it at the bottom [SPEC 16.1/16.2].
    |J#J1| "JST XH" { pins: 2; cell: 1 1; mirror: y-axis; }
    |F#F1| "2A"
    |D#D1| "SMAJ24A" { symbol: tvs; }
    |R#R1| "100k"
    |C#C1| "470u" { symbol: polarized; }

    // Reverse-polarity protection. `cell:` places an anchor on the scope's own
    // stands off the tach trace instead of queueing in a second lane beside the
    // connector.
    J4.p2 - tach
    tach - R16 - |v3|
  ]

  |title-block| {
    title: "Bench motor node"; drawing-number: "LN-0057"; revision: "C"; sheet-number: "1/1"; date: "2026-08-30"; author: "AM";
  }
]
  |vm::label| { symbol: power; } [
    "VM"
  ]

  |region::group| { layout: schematic; padding: 60 20; }
}

|page| {
  sheet: a3 landscape; layout: grid; padding: 0; columns: 800, 1000; gap: 10;
} [

  |region#boost| "5.5v Boost" { cell: 1 1; } [
    |component#U6| "TPS61023DRLR" [
      |pin#VIN| { side: left; number: 3; }
      // A `|space|` is one empty slot on the rail of the pin before it, and
      // `span: N` makes it N [SPEC 16.2]: the switch node stands clear of the
      // input above and the enable below, the way the datasheet groups them,
      // so the inductor's readouts and the enable's name each keep a row.
      |space|
      |pin#SW| { side: left; number: 5; }
      |space| { span: 2; }
    // to the resistor — a through point, not a second lead [SPEC 16.4].
    U8.BRA - "RS_A"
    U8.BRA - R20 - |gnd|
    U8.BRB - "RS_B"
    U8.BRB - R21 - |gnd|
  ]

  |title-block| {
    title: "Boost and stepper blocks"; drawing-number: "LN-0058"; revision: "A"; sheet-number: "1/1"; date: "2026-08-31"; author: "AM";
  }
]

