23	// The pseudo-type classes tables put on their cells: (property, value).
24	// They cascade below everything else (a user's |block| rule still wins).
25	pub fn pseudo_class(t: &str) -> Option<(&'static str, &'static str)> {
26	    match t {
27	        "align-start" => Some(("align", "start")),
28	        "align-end" => Some(("align", "end")),
29	        "justify-start" => Some(("justify", "start")),
30	        "justify-end" => Some(("justify", "end")),
31	        _ => None,
32	    }
33	}
34	
35	pub fn pseudo_value(v: &str) -> Value {
36	    Value { groups: vec![vec![Term::Ident(v.to_string(), Span::default())]], span: Span::default() }
37	}
38	
39	// Parse a declaration list written by the lowering (not user text).
40	pub fn parse_decls(src: &str) -> Vec<Decl> {
41	    let full = format!("{{{}}}", src);
42	    let lexed = match crate::lexer::lex(&full) {
43	        Ok(l) => l,
44	        Err(_) => return vec![],
45	    };
46	    let mut p = crate::parser::Parser::new(&lexed.tokens, &full);
47	    match p.parse_style_block() {
48	        Ok((decls, _)) => decls
49	            .into_iter()
50	            .map(|mut d| {
51	                d.span = Span::default();
52	                d.name_span = Span::default();
53	                d.value.span = Span::default();
54	                d
55	            })
56	            .collect(),
57	        Err(_) => vec![],
58	    }
59	}
60	
61	fn set_decl(decls: &mut Vec<Decl>, d: Decl) {
62	    decls.retain(|e| e.name != d.name);
63	    decls.push(d);
64	}
65	
66	// Number of column tracks a `columns:` value declares.
67	pub fn track_count(env: &Env, v: &Value) -> usize {
68	    let mut n = 0usize;
69	    for g in &v.groups {
70	        for t in g {
71	            match t {
72	                Term::Ident(s, _) if s == "auto" => n += 1,
73	                Term::Call(name, args, _) if name == "repeat" => {
74	                    let k = args
75	                        .first()
76	                        .and_then(|a| env.eval(a, &Default::default()).ok())
77	                        .and_then(|x| x.num())
78	                        .unwrap_or(1.0);
79	                    n += k.max(0.0) as usize;
80	                }
81	                _ => {
82	                    if crate::style::term_num(env, t).is_some() {
83	                        n += 1;
84	                    }
85	                }
86	            }
87	        }
88	    }
89	    n
90	}
91	
92	fn get<'a>(props: &'a [(String, Value)], k: &str) -> Option<&'a Value> {
93	    props.iter().rev().find(|e| e.0 == k).map(|e| &e.1)
94	}
