96	// The keyword list of an `align:` / `justify:` value, one entry per group.
97	fn keyword_list(v: &Value) -> Vec<String> {
98	    v.groups
99	        .iter()
100	        .map(|g| match g.first() {
101	            Some(Term::Ident(s, _)) => s.clone(),
102	            _ => String::new(),
103	        })
