122	// A cell lowered from a bare string: |block| .lini-cell.lini-block [ "text" ].
123	fn string_cell(b: &mut Builder, t: &TextStmt, parent: usize) -> Result<usize, Diag> {
124	    b.check_classes(&t.classes, t.span)?;
